#include <Wire.h>
#include <BH1750.h>
#include <Adafruit_NeoPixel.h>

// Пины (XIAO ESP32-C3): SDA=D4, SCL=D5, D0=D0, D1=D1, D2=D2
#define PIN_PIR   D0
#define PIN_BTN   D1
#define PIN_LED   D2
#define NUM_LEDS 1

BH1750 lightMeter;
Adafruit_NeoPixel strip(NUM_LEDS, PIN_LED, NEO_GRB + NEO_KHZ800);

// Настройки
float LUX_THRESHOLD = 15.0; // ниже — считается темно
uint32_t LIGHT_DURATION_MS = 15000; // сколько гореть после движения
uint8_t BRIGHTNESS = 80; // 0-255
bool warmOnly = true;

unsigned long lastMotion = 0;
bool isOn = false;
unsigned long btnPress = 0;

void setup(){
  Serial.begin(115200);
  pinMode(PIN_PIR, INPUT);
  pinMode(PIN_BTN, INPUT_PULLUP);
  Wire.begin(SDA, SCL); // SDA=D4 SCL=D5 на XIAO
  if(lightMeter.begin(BH1750::CONTINUOUS_HIGH_RES_MODE)) Serial.println("BH1750 OK");
  else Serial.println("BH1750 not found - работа без датчика света");
  strip.begin();
  strip.setBrightness(BRIGHTNESS);
  strip.clear(); strip.show();
}

void setLight(bool on){
  isOn = on;
  if(on){
    if(warmOnly) strip.setPixelColor(0, 255, 180, 80); // тёплый белый
    else strip.setPixelColor(0, 100, 150, 255);
  } else strip.clear();
  strip.show();
}

void loop(){
  // Кнопка: короткое нажатие — переключить яркость/цвет, длинное 2с — выкл
  if(digitalRead(PIN_BTN)==LOW){
    if(btnPress==0) btnPress=millis();
  } else {
    if(btnPress!=0){
      unsigned long d=millis()-btnPress;
      if(d>2000){ setLight(false); }
      else {
        // цикл яркости
        if(BRIGHTNESS<60) BRIGHTNESS=80;
        else if(BRIGHTNESS<130) BRIGHTNESS=180;
        else BRIGHTNESS=30;
        strip.setBrightness(BRIGHTNESS);
        if(isOn) setLight(true);
      }
      btnPress=0;
      delay(200);
    }
  }

  float lux = -1;
  if(lightMeter.measurementReady()) lux = lightMeter.readLightLevel();
  else lux = lightMeter.readLightLevel(); // пробуем
  bool dark = true;
  if(lux>=0) dark = (lux < LUX_THRESHOLD);
  // PIR
  bool motion = digitalRead(PIN_PIR)==HIGH;
  if(motion){
    lastMotion = millis();
    if(dark && !isOn) setLight(true);
  }
  if(isOn && millis()-lastMotion > LIGHT_DURATION_MS){
    setLight(false);
  }
  // если стало светло — гасим
  if(isOn && !dark && lux>=0) setLight(false);

  delay(100);
}
